using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DecimatorSkullOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/DecimatorSkull Omen Data")]
public class DecimatorSkullOmenData : IncreasePurifyReceivedByEnemiesOmenData
{
	private const string increaseCorruptionReceivedByEnemiesID = "IncreaseCorruptionReceivedByEnemies";

	[Header("Decimator Skull")]
	[SerializeField]
	private int additionalCorruptionAmount;

	private Func<int, int> purifyOmenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		Func<int, int> onEnemyCorruptedDecimatorSkullModifierOmenAction = delegate(int corruptAmount)
		{
			corruptAmount += additionalCorruptionAmount;
			omenInstance.EnqueueOmenFeedbackAndPlay();
			return corruptAmount;
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.OnEnemyCorruptedDecimatorSkullModifierOmenAction = onEnemyCorruptedDecimatorSkullModifierOmenAction;
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnEnemyCorruptedDecimatorSkullModifierOmenAction = null;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return GetIncreasePurifyReceivedByEnemiesLocalizedString() + "\n" + Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("IncreaseCorruptionReceivedByEnemies"), additionalCorruptionAmount);
	}
}
